/*
 * A002110  Primorial numbers (first definition): product of first n primes.
 *          Sometimes written prime(n)#.
 * https://oeis.org/A002110
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy, nice, core, changed
 * Formula:   a(n) = prime(n)*a(n-1), a(0) = 1 (primes generated by trial
 *            division)
 * Range:     u8 n <= 4, u16 n <= 6, u32 n <= 9, u64 n <= 15, u128 n <= 26,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>

static uint64_t *a002110_primes = NULL;
static size_t a002110_count = 0;
static size_t a002110_cap = 0;

static void a002110_ensure(size_t need)
{
    uint64_t c;
    if (a002110_count >= need)
        return;
    if (a002110_cap < need) {
        size_t nc = a002110_cap ? a002110_cap : 64;
        uint64_t *np;
        while (nc < need)
            nc *= 2;
        np = (uint64_t *)realloc(a002110_primes, nc * sizeof(uint64_t));
        if (!np)
            return;
        a002110_primes = np;
        a002110_cap = nc;
    }
    c = a002110_count ? a002110_primes[a002110_count - 1] + 1 : 2;
    while (a002110_count < need) {
        int isp = 1;
        size_t i;
        for (i = 0; i < a002110_count; i++) {
            uint64_t p = a002110_primes[i];
            if (p * p > c)
                break;
            if (c % p == 0) {
                isp = 0;
                break;
            }
        }
        if (isp)
            a002110_primes[a002110_count++] = c;
        c++;
    }
}

seq_t a(idx_t n)
{
    seq_t result = 1;
    idx_t i;
    a002110_ensure((size_t)n);
    for (i = 0; i < n; i++)
        result *= (seq_t)a002110_primes[i];
    return result;
}
